import{_ as r,a,b as d}from"./chunks/steam-board.DPsXOloe.js";import{_ as e,o,c as b,a0 as h}from"./chunks/framework.DZqO77tS.js";const u=JSON.parse('{"title":"EcoCONNECT 技術資料","description":"","frontmatter":{},"headers":[],"relativePath":"docs/hack/internal.md","filePath":"docs/hack/internal.md"}'),i={name:"docs/hack/internal.md"};function n(l,t,s,c,P,p){return o(),b("div",null,[...t[0]||(t[0]=[h('<h1 id="ecoconnect-技術資料" tabindex="-1">EcoCONNECT 技術資料 <a class="header-anchor" href="#ecoconnect-技術資料" aria-label="Permalink to &quot;EcoCONNECT 技術資料&quot;">​</a></h1><h2 id="構成とスペック" tabindex="-1">構成とスペック <a class="header-anchor" href="#構成とスペック" aria-label="Permalink to &quot;構成とスペック&quot;">​</a></h2><p>EcoCONNECTはメインボード、STEAM ボードで構成されています。 アルカリ乾電池3本、またはUSB電源で稼働し、複数の自由に使用できるコネクタ線を搭載するIoTデバイスです。</p><p><img src="'+r+'" alt="summary"></p><h3 id="スペック" tabindex="-1">スペック <a class="header-anchor" href="#スペック" aria-label="Permalink to &quot;スペック&quot;">​</a></h3><table tabindex="0"><thead><tr><th>MPU</th><th>Raspberry Pi Pico2</th></tr></thead><tbody><tr><td>データ通信</td><td>LoRaWAN（A660-900T22）</td></tr><tr><td>開発言語</td><td>MicroPython</td></tr><tr><td>センサー</td><td>気温/湿度/気圧（BME280）、照度（BH1750）</td></tr><tr><td>電源</td><td>アルカリ乾電池3本</td></tr></tbody></table><h3 id="メインボード" tabindex="-1">メインボード <a class="header-anchor" href="#メインボード" aria-label="Permalink to &quot;メインボード&quot;">​</a></h3><h4 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h4><p>メインボードは各センサーデバイスからのデータを処理し、データを送信する4層基板のボードです。 MPUにはRaspberry Pi Pico2を使用し、LoRaWANモジュール（A660-900T22）とシリアル通信で接続されています。 また、I2Cバスを使用してSTEAMボードのセンサーとデータ通信をします。</p><p>LoRaWANモジュール（A660-900T22）はモジュール単体、または評価版モジュールのどちらかを搭載できます。 LoRaWANの動作を確認したい場合には、ピンヘッダーを使用して評価モジュールを搭載するとデバッグがスムーズにできます。</p><h4 id="ピンアサイン" tabindex="-1">ピンアサイン <a class="header-anchor" href="#ピンアサイン" aria-label="Permalink to &quot;ピンアサイン&quot;">​</a></h4><p>各コネクタの役割とピンアサインです。STEAMボードを使用する場合は、J1/J2コネクタが使用されます。 拡張用コネクタ(J4/6)のピンは自由に使用できます。 ファームウェアアップデート用コネクタ（J7）はLoRaWANモジュールのファームウェアを更新する際に使用します。 アドオンボード用コネクタ（J5/8）のピンは予約ピンで、将来の拡張ように使用されます。</p><table tabindex="0"><thead><tr><th>コネクタ名</th><th>ピンアサイン</th><th>用途</th></tr></thead><tbody><tr><td>J1</td><td>1 : GND<br>2 : VBAT sens.<br>3 : VBAT <br>　4 : Reserve</td><td>バッテリに接続</td></tr><tr><td>J2</td><td>1 : SCL<br>3 : SDA<br>5 : 3V3<br>2/4/6/7/8 : GND</td><td>STEAMボードに接続</td></tr><tr><td>J4</td><td>1 : VBUS<br>2 : 3V3_EN<br>3 : 3V3<br>4 : ADC_VREF<br>5 : AGND<br>6 : GPIO19<br>7 : GPIO18<br>8 : GPIO17</td><td>拡張用コネクタ<br>（Raspberry Pi Picoの各ピンに接続）</td></tr><tr><td>J5/J8</td><td>1 : GPIO16<br>4 : VSYS<br>6 : J8 P4<br>7 : J8 P5<br>10 : J8 P1<br>2/3/5/8/9/11/12 : GND</td><td>アドオンボード（予定）用</td></tr><tr><td>J6</td><td>1 : GPIO2<br>2 : GPIO4<br>3 : GPIO5<br>4 : GPIO6<br>5 : GPIO7<br>6 : GPIO8<br>7 : GPIO9<br>8 : GPIO10<br>9 : GPIO11<br>10 : GPIO12 <br>11 : GPIO13<br>12 : GPIO15</td><td>拡張用コネクタ<br>（Raspberry Pi Picoの各ピンに接続）</td></tr><tr><td>J7</td><td>1 : VCC<br>2 : CTS<br>3 : SETB<br>4 : GND<br>5 : TXG<br>6 : XRES</td><td>ファームウェアアップデート（A660-900T）用</td></tr></tbody></table><h4 id="物理スペックとコネクタの位置" tabindex="-1">物理スペックとコネクタの位置 <a class="header-anchor" href="#物理スペックとコネクタの位置" aria-label="Permalink to &quot;物理スペックとコネクタの位置&quot;">​</a></h4><p><img src="'+a+'" alt="main board"></p><h3 id="steamボード" tabindex="-1">STEAMボード <a class="header-anchor" href="#steamボード" aria-label="Permalink to &quot;STEAMボード&quot;">​</a></h3><h4 id="概要-1" tabindex="-1">概要 <a class="header-anchor" href="#概要-1" aria-label="Permalink to &quot;概要&quot;">​</a></h4><p>環境センサー（温度・湿度・環境光・気圧）を搭載した４層基板で構成されています。各センサーは1本のI2CバスでMPUと通信します。</p><p>想定される搭載センサーはBME280（温湿度、気圧）とBH1750（照度）で、BME280は基板表面、BH1750は基板裏面に搭載します。</p><p>プルアップレジスタ（R1/2）は使用するセンサーモジュールに搭載されない場合に適宜追加してください。</p><h4 id="ピンアサイン-1" tabindex="-1">ピンアサイン <a class="header-anchor" href="#ピンアサイン-1" aria-label="Permalink to &quot;ピンアサイン&quot;">​</a></h4><table tabindex="0"><thead><tr><th>コネクタ名</th><th>ピンアサイン</th><th>用途</th></tr></thead><tbody><tr><td>J1</td><td>1 : SDA<br>3 : SCL<br>5 : 3V3<br>2/4/6/7/8 : GND</td><td>メインボードに接続</td></tr><tr><td>J2</td><td>1 : ADDR<br>2 : SDA<br>3 : SCL<br>4 : GND<br>5 : 3V3</td><td>BH1750（基板裏面）<br>に接続</td></tr><tr><td>J3</td><td>1 : SDO<br>2 : SCL<br>3 : SDA<br>4 : CSR<br>5 : GND<br>6 : Vcore<br>7 : VIO</td><td>BME280（基板表面）<br>に接続</td></tr></tbody></table><h4 id="物理スペックとコネクタの位置-1" tabindex="-1">物理スペックとコネクタの位置 <a class="header-anchor" href="#物理スペックとコネクタの位置-1" aria-label="Permalink to &quot;物理スペックとコネクタの位置&quot;">​</a></h4><p><img src="'+d+'" alt="steam board"></p>',24)])])}const S=e(i,[["render",n]]);export{u as __pageData,S as default};
